use vstd::prelude::*;

verus! {
    fn is_greater(n: i32, a: &Vec<i32>) -> bool
        requires
            a.len() > 0, // The array must be non-empty
        ensures
            result == (forall |i: nat| (i < a.len() as nat) ==> n > a[i as usize]),
    {
        let mut idx: nat = 0; // Initialize index
        let mut result: bool = true; // Assume n is greater than all elements

        while idx < a.len() as nat
            invariant
                idx <= a.len() as nat, // idx must be within bounds of the array
                result == (forall |j: nat| (j < idx) ==> n > a[j as usize]), // Maintain the result condition
            decreases a.len() as nat - idx, // Ensure the loop decreases
        {
            if n <= a[idx as usize] {
                result = false; // If n is not greater than a[idx], set result to false
            }
            idx = idx + 1; // Move to the next index
        }

        result // Return the final result
    }
}
